"""wtask.schedule —— 触发时间计算。

本模块只做「给定任务与起始时刻，算出接下来的若干次运行时刻」这件事。
所有计算都在**本地 naive 时间**上进行（不涉及时区与夏令时）。
"""

import calendar
from datetime import datetime, timedelta

from .errors import TaskDefError

#: 主出现扫描的最大跨度（天）。超出该跨度的任务定义视为不可调度。
HORIZON_DAYS = 4000

#: ``plan_window`` 一次最多枚举多少次运行。
PLAN_HARD_LIMIT = 20000


# ------------------------------------------------------------------ 日历工具


def _weekday_index(day):
    """Python 的 ``date.weekday()`` 是 Monday=0..Sunday=6；本模块统一用 Sunday=0。"""
    return (day.weekday() + 1) % 7


def _week_start(day):
    """返回 ``day`` 所在周（周一起始）的周一。"""
    return day - timedelta(days=day.weekday())


def _week_index(day):
    """返回 ``day`` 在本月内的日历周序号（1 起）。

    1–7 日为第 1 周，8–14 日为第 2 周，15–21 日为第 3 周，
    22–28 日为第 4 周，29 日及以后为第 5 周。
    """
    return (day.day - 1) // 7 + 1


def _weeks_in_month(day):
    """返回 ``day`` 所在月份共有多少个「日历周」（4 或 5）。"""
    days_in_month = calendar.monthrange(day.year, day.month)[1]
    return (days_in_month + 6) // 7


def _match_week(day, wanted):
    """``<Week>`` 匹配。

    1..4 表示第 n 周；**5 表示该月的最后一周**（可能是第 4 周，例如平年 2 月）。
    """
    index = _week_index(day)
    last = _weeks_in_month(day)
    for w in wanted:
        if w == 5:
            if index == last:
                return True
        elif index == w:
            return True
    return False


def _day_matches(trigger, day):
    """``day`` 这一天是否是这个触发器的一个主出现日（不看时刻）。"""
    if trigger.type == "daily":
        # 锚点是 StartBoundary 的日期：(当天 − StartBoundary 日期).days % N == 0
        return (day - trigger.start.date()).days % trigger.days_interval == 0

    if trigger.type == "weekly":
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        # 周按周一起始划分；StartBoundary 所在的周为第 0 周，
        # 之后每隔 WeeksInterval 周触发一次。
        weeks = (_week_start(day) - _week_start(trigger.start.date())).days // 7
        return weeks % trigger.weeks_interval == 0

    if trigger.type == "monthly":
        if day.month not in trigger.months:
            return False
        return day.day in trigger.days_of_month

    if trigger.type == "monthly_dow":
        if day.month not in trigger.months:
            return False
        if _weekday_index(day) not in trigger.days_of_week:
            return False
        return _match_week(day, trigger.weeks_of_month)

    raise TaskDefError("trigger", "unknown trigger type: %r" % (trigger.type,))


# ------------------------------------------------------------------ 出现时刻


def _primary_occurrences(trigger, after, limit):
    """产出主出现时刻（升序）。

    只保留可能在 ``(after, limit]`` 内产生运行时刻的主出现；
    更早的主出现要么自身不晚于 ``after``，要么连同其重复序列一起
    够不到 ``after``。
    """
    if trigger.type == "time":
        if trigger.end is not None and trigger.start > trigger.end:
            return []
        return [trigger.start]

    repetition = trigger.repetition
    if repetition is None:
        # 无重复：只有晚于 after 的主出现有用
        earliest = after
    elif repetition.duration is not None:
        # 重复序列延伸到 主出现 + Duration（开区间）为止
        earliest = after - repetition.duration
    else:
        # 不限时长的重复：任意旧主出现都可能覆盖 after 之后的时刻
        earliest = None

    stop = limit.date()
    if trigger.end is not None and trigger.end.date() < stop:
        stop = trigger.end.date()

    out = []
    day = trigger.start.date()
    tod = trigger.start.time()
    while day <= stop:
        if _day_matches(trigger, day):
            moment = datetime.combine(day, tod)
            if trigger.end is not None and moment > trigger.end:
                break
            if earliest is None or moment > earliest:
                out.append(moment)
        day += timedelta(days=1)
    return out


def _expand(trigger, occurrence, after, limit, count):
    """把一次主出现展开为 ``(after, limit]`` 内的实际运行时刻（至多 ``count`` 个）。

    存在 ``<Repetition>`` 时，保留 ``T + k×Interval``（k = 0, 1, 2, …）
    中满足 ``k×Interval < Duration`` 的时刻；重复时刻同样受
    ``EndBoundary`` 约束（晚于 ``EndBoundary`` 的不触发）。
    """
    if occurrence > limit:
        return []
    repetition = trigger.repetition
    if repetition is None:
        return [occurrence] if occurrence > after else []

    interval = repetition.interval
    if occurrence > after:
        k_min = 0
    else:
        # occurrence + k×interval > after 的最小 k
        k_min = (after - occurrence) // interval + 1

    k_max = k_min + count - 1
    if repetition.duration is not None:
        # 只保留满足 k×Interval < Duration 的项
        q, r = divmod(repetition.duration, interval)
        k_max = min(k_max, q - 1 if r == timedelta(0) else q)
    if trigger.end is not None:
        # 重复时刻同样受 EndBoundary 约束（== EndBoundary 仍触发）
        k_max = min(k_max, (trigger.end - occurrence) // interval)
    k_max = min(k_max, (limit - occurrence) // interval)

    if k_max < k_min:
        return []
    return [occurrence + k * interval for k in range(k_min, k_max + 1)]


# ------------------------------------------------------------------ 公共 API


def _collect(task, after, limit, count):
    """汇总所有启用触发器在 ``(after, limit]`` 内的运行时刻（去重）。"""
    moments = set()
    for trigger in task.triggers:
        if not trigger.enabled:
            continue
        for occurrence in _primary_occurrences(trigger, after, limit):
            moments.update(_expand(trigger, occurrence, after, limit, count))
            if len(moments) > PLAN_HARD_LIMIT:
                return moments
    return moments


def next_runs(task, after, count):
    """返回 ``after`` 之后最近的 ``count`` 次运行时刻（升序、去重）。

    * 任务被禁用（``task.enabled`` 为假）时返回空列表；
    * 触发器被禁用（``trigger.enabled`` 为假）时跳过该触发器；
    * 返回的时刻**严格大于** ``after``；不足 ``count`` 次时返回实际数量。
    """
    if not task.enabled:
        return []
    if count <= 0:
        return []
    limit = after + timedelta(days=HORIZON_DAYS)
    moments = _collect(task, after, limit, count)
    return sorted(moments)[:count]


def plan_window(task, start, end):
    """返回位于 ``(start, end]`` 区间内的全部运行时刻（升序、去重）。"""
    if not task.enabled:
        return []
    if end < start:
        return []
    moments = _collect(task, start, end, PLAN_HARD_LIMIT)
    return sorted(moments)[:PLAN_HARD_LIMIT]


def validate_task(task):
    """跨字段一致性校验；不一致时抛 ``TaskDefError``。"""
    for trigger in task.triggers:
        if trigger.end is not None and trigger.end < trigger.start:
            raise TaskDefError(
                "structure",
                "EndBoundary %s is earlier than StartBoundary %s"
                % (trigger.end.isoformat(), trigger.start.isoformat()),
            )
    return task

